exercises.solution:
function is1NF(row) {
  return Object.values(row).every(v => typeof v !== "object" || v === null);
}
console.log(is1NF({ id: 1, name: "Ava" }));
console.log(is1NF({ id: 2, phones: ["555-01"] }));

