exercises.solution:
const orders = [
  { order_id: 1, customer: "Ava", phone: "555-01" },
  { order_id: 2, customer: "Ava", phone: "555-01" },
  { order_id: 3, customer: "Ben", phone: "555-02" },
];
const seen = new Map();
for (const o of orders) {
  if (!seen.has(o.customer)) seen.set(o.customer, o.phone);
}
const customers = [...seen].map(([name, phone]) => ({ name, phone }));
const slim = orders.map(o => ({ order_id: o.order_id, customer: o.customer }));
console.log("customers:", customers.length);
console.log("phones stored:", customers.length);
console.log("slim keys:", Object.keys(slim[0]).join(","));

