exercises.solution:
function hasTransitiveDep(rows) {
  const byCity = {};
  for (const r of rows) {
    if (byCity[r.city] !== undefined && byCity[r.city] !== r.taxRate) return true;
    byCity[r.city] = r.taxRate;
  }
  return false;
}
const ok = [
  { id: 1, city: "Calgary", taxRate: 0.05 },
  { id: 2, city: "Edmonton", taxRate: 0.05 },
];
const bad = [
  { id: 1, city: "Calgary", taxRate: 0.05 },
  { id: 2, city: "Calgary", taxRate: 0.09 },
];
console.log(hasTransitiveDep(ok));
console.log(hasTransitiveDep(bad));
